class Solution {
  public int maximumGap(String skill, String station) {
    int n = skill.length(), m = station.length();
    if (n == 1) return 0;
    int[] pre = new int[n], suf = new int[n];
    int p = 0;
    for (int i = 0; i < n; i++) {
      while (station.charAt(p) != skill.charAt(i)) p++;
      pre[i] = p++;
    }
    p = m - 1;
    for (int i = n - 1; i >= 0; i--) {
      while (station.charAt(p) != skill.charAt(i)) p--;
      suf[i] = p--;
    }
    int best = 0;
    for (int i = 1; i < n; i++) best = Math.max(best, suf[i] - pre[i - 1]);
    return best;
  }
}
